import threading
import time
import hashlib
import secrets
import json
from datetime import datetime, timedelta
from functools import wraps

# Secure token generation
def generate_token():
    return secrets.token_urlsafe(32)

def hash_token(token):
    return hashlib.sha256(token.encode('utf-8')).hexdigest()

class SessionStore:
    """Thread-safe session store with revocation support."""

    def __init__(self):
        self._sessions = {}
        self._revoked = set()
        self._lock = threading.RLock()

    def create_session(self, user_id, role, ttl_seconds=3600):
        token = generate_token()
        token_hash = hash_token(token)
        with self._lock:
            self._sessions[token_hash] = {
                'user_id': user_id,
                'role': role,
                'created_at': datetime.utcnow(),
                'expires_at': datetime.utcnow() + timedelta(seconds=ttl_seconds),
                'token_hash': token_hash
            }
        return token

    def validate_session(self, token):
        """Validate token and return session data if valid."""
        token_hash = hash_token(token)
        with self._lock:
            # Check revocation within the same lock acquisition
            # to ensure atomicity of validation + revocation check
            if token_hash in self._revoked:
                return None
            session = self._sessions.get(token_hash)
            if session is None:
                return None
            if datetime.utcnow() > session['expires_at']:
                del self._sessions[token_hash]
                return None
            return session.copy()

    def revoke_session(self, token):
        """Revoke a specific session token."""
        token_hash = hash_token(token)
        with self._lock:
            self._revoked.add(token_hash)
            if token_hash in self._sessions:
                del self._sessions[token_hash]

    def revoke_all_user_sessions(self, user_id):
        """Revoke all sessions for a user (e.g., after role change)."""
        with self._lock:
            to_revoke = [
                th for th, s in self._sessions.items()
                if s['user_id'] == user_id
            ]
            for token_hash in to_revoke:
                self._revoked.add(token_hash)
                del self._sessions[token_hash]


class RoleManager:
    """Manages user roles with proper session invalidation."""

    def __init__(self, session_store):
        self._users = {}
        self._lock = threading.RLock()
        self._session_store = session_store

    def add_user(self, user_id, role='viewer'):
        with self._lock:
            self._users[user_id] = {'role': role, 'updated_at': datetime.utcnow()}

    def get_role(self, user_id):
        with self._lock:
            user = self._users.get(user_id)
            return user['role'] if user else None

    def update_role(self, actor_session, target_user_id, new_role):
        """Update a user's role. Only admins can do this."""
        if actor_session is None:
            return {'error': 'Not authenticated', 'status': 401}

        if actor_session['role'] != 'admin':
            return {'error': 'Insufficient permissions', 'status': 403}

        if actor_session['user_id'] == target_user_id:
            return {'error': 'Cannot modify own role', 'status': 403}

        valid_roles = ('admin', 'editor', 'viewer')
        if new_role not in valid_roles:
            return {'error': 'Invalid role', 'status': 400}

        with self._lock:
            if target_user_id not in self._users:
                return {'error': 'User not found', 'status': 404}
            self._users[target_user_id] = {
                'role': new_role,
                'updated_at': datetime.utcnow()
            }

        # Invalidate all sessions for the target user so they
        # must re-authenticate with new permissions
        self._session_store.revoke_all_user_sessions(target_user_id)

        return {'success': True, 'status': 200}


class APIGateway:
    """Simulates an API gateway with authentication."""

    def __init__(self, session_store, role_manager):
        self._session_store = session_store
        self._role_manager = role_manager

    def handle_request(self, token, action, params):
        """Process an API request."""
        session = self._session_store.validate_session(token)

        if action == 'update_role':
            return self._role_manager.update_role(
                session,
                params.get('target_user_id'),
                params.get('new_role')
            )
        elif action == 'get_sensitive_data':
            return self._handle_sensitive_data(session)
        elif action == 'admin_action':
            return self._handle_admin_action(session, params)
        else:
            return {'error': 'Unknown action', 'status': 404}

    def _handle_sensitive_data(self, session):
        if session is None:
            return {'error': 'Not authenticated', 'status': 401}
        if session['role'] not in ('admin', 'editor'):
            return {'error': 'Insufficient permissions', 'status': 403}
        return {'data': 'sensitive_content_here', 'status': 200}

    def _handle_admin_action(self, session, params):
        if session is None:
            return {'error': 'Not authenticated', 'status': 401}
        if session['role'] != 'admin':
            return {'error': 'Insufficient permissions', 'status': 403}
        return {'result': f'Admin action executed: {params.get("cmd", "none")}', 'status': 200}


def demonstrate_concurrent_access():
    """Demonstrates the system under concurrent access."""
    store = SessionStore()
    manager = RoleManager(store)
    gateway = APIGateway(store, manager)

    # Setup users
    manager.add_user('alice', 'admin')
    manager.add_user('bob', 'admin')

    # Alice and Bob both have admin tokens
    alice_token = store.create_session('alice', 'admin')
    bob_token = store.create_session('bob', 'admin')

    results = []

    def alice_demotes_bob():
        """Alice demotes Bob to viewer."""
        time.sleep(0.01)  # Small delay to simulate network
        result = gateway.handle_request(alice_token, 'update_role', {
            'target_user_id': 'bob',
            'new_role': 'viewer'
        })
        results.append(('alice_demotes', result))

    def bob_uses_admin():
        """Bob tries to perform admin action."""
        time.sleep(0.005)
        result = gateway.handle_request(bob_token, 'admin_action', {
            'cmd': 'delete_all_users'
        })
        results.append(('bob_admin', result))

    t1 = threading.Thread(target=alice_demotes_bob)
    t2 = threading.Thread(target=bob_uses_admin)

    t1.start()
    t2.start()
    t1.join()
    t2.join()

    return results


if __name__ == '__main__':
    results = demonstrate_concurrent_access()
    for name, result in results:
        print(f"{name}: {result}")
